<?php foreach($vendos as $v):$settings=$v['feature_settings']??[];$resolved=$v['resolved_features']??[];$hasVendo=(bool)($v['has_vendo']??trim((string)($v['base_url']??''))!=='');?><tr>
<td><strong><?= e($v['name']) ?></strong><div class="small text-body-secondary"><?= e($v['router_identity']) ?></div></td><td><?= $hasVendo?'<span class="badge text-bg-primary">Connected</span>':'<span class="badge text-bg-secondary">None</span>' ?></td><td class="code"><?= e($v['server_ip']?:'—') ?></td><td><?= $v['portal_theme_id']?'Custom':'Router' ?></td>
<td><div class="d-flex flex-wrap gap-1"><?php foreach($featureLabels as $key=>$label):$custom=array_key_exists($key,$settings)&&$settings[$key]['value']!==null;$on=(bool)($resolved[$key]['enabled']??false);if($key==='coin_slot'&&!$hasVendo)$on=false;?><span class="badge <?= $on?'text-bg-success':'text-bg-secondary' ?>" title="<?= $key==='coin_slot'&&!$hasVendo?'Requires Vendo hardware':($custom?'Station override':'Inherited from router') ?>"><?= e($label) ?>: <?= $on?'On':'Off' ?><?= $custom?' *':'' ?></span><?php endforeach;?></div></td>
<td><?= $v['enabled']?'Enabled':'Disabled' ?></td><?php if($canManageVendos):?><td class="text-end"><div class="d-flex gap-1 justify-content-end"><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#featuresModal" data-id="<?= e($v['id']) ?>" data-name="<?= e($v['name']) ?>" data-features='<?= e(json_encode($settings)) ?>'>Features</button><button class="btn btn-sm btn-outline-secondary" data-bs-toggle="modal" data-bs-target="#stationModal" data-mode="edit" data-id="<?= e($v['id']) ?>" data-name="<?= e($v['name']) ?>" data-router="<?= e($v['router_id']) ?>" data-theme="<?= e($v['portal_theme_id']??0) ?>" data-url="<?= e(preg_replace('~^https?://~i','',(string)$v['base_url'])) ?>" data-server-ip="<?= e($v['server_ip']??'') ?>" data-subnet="<?= e($v['client_subnet']??'') ?>" data-interface="<?= e($v['interface_name']??'') ?>" data-password-mode="<?= e($v['password_mode']) ?>" data-charging="<?= $v['charging_enabled']?'1':'0' ?>" data-eload="<?= $v['eload_enabled']?'1':'0' ?>" data-enabled="<?= $v['enabled']?'1':'0' ?>">Edit</button></div></td><?php endif;?></tr><?php endforeach;?>
